            L = np.linalg.pinv(M, rcond=1e-12) @ X[:n].T
            c = L @ y
            if not loo:
                return (X, c)
            h = (X[:n] * L.T).sum(1)
            e = y - X[:n] @ c
        return np.mean((e / np.maximum(1 - h, 0.02)) ** 2)
    if freq == 0:
        ws = [0.1, 0.22, 0.4, 0.65, 1.0, 2.0, 4.0]
        w0 = min(ws, key=lambda w: train(w, True))
        j = ws.index(w0)
